@Component("pharmacy-handler")
@ProcessingGroup("pharmacy-processing-group")
public class PharmacyEventHandler {
	
	// core constructor
	PharmacyEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreatePharmacyEvent
     */
    @EventHandler
    public void handle( CreatePharmacyEvent event) {
        entityManager.persist(new Pharmacy(event.getPharmacyId(), event.getName(), event.getFacility(), event.getMedicationDispenses(), event.getMedicationOrders()));
    }

    /*
     * @param	event UpdatePharmacyEvent
     */
    @EventHandler
    public Pharmacy handle( UpdatePharmacyEvent event) {
    	entityManager.merge(new Pharmacy(event.getPharmacyId(), event.getName(), event.getFacility(), event.getMedicationDispenses(), event.getMedicationOrders()));
    }
    
    /*
     * @param	event DeletePharmacyEvent
     */
    @EventHandler
    public void on( DeletePharmacyEvent event) {
    	Pharmacy entity = new Pharmacy();
   
    	// ------------------------------------------
    	// apply the PharmacyId
    	// ------------------------------------------
    	entity.setPharmacyId( event.getPharmacyId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final PharmacyRepository pharmacyEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(PharmacyEventHandler.class.getName());

}
